namespace FortiSplit.Work;

internal sealed record SettingsHelpTopic(string Title,string Summary,string Instructions,string Example="")
{
 internal string Content()
 {
  return Summary+(Example.Length>0?"\r\n\r\nВымышленный пример (замените своими данными):\r\n"+Example:"")+"\r\n\r\n"+Instructions;
 }
}

internal static class SettingsHelp
{
 private static readonly Dictionary<string,SettingsHelpTopic> Topics=new()
 {
  ["auto-rdp"]=new("Открывать RDP после подключения","Автоматически открывает выбранный рабочий стол после готовности VPN.",
   "Включите, если после подключения всегда нужен удалённый рабочий стол. Сначала выберите файл в пункте «Рабочий стол».\r\n\r\nОставьте выключенным, если хотите запускать RDP вручную кнопкой «Открыть RDP» на вкладке «Работа»."),
  ["auto-tc"]=new("Открывать TrueConf после подключения","Запускает программу TrueConf после готовности VPN.",
   "Включите, если используете рабочие видеозвонки. Укажите программу и сервер TrueConf в дополнительных настройках.\r\n\r\nЕсли TrueConf не нужен, оставьте галочку выключенной, а его поля — пустыми. Это не мешает работе VPN и сайтов."),
  ["auto-connect"]=new("Подключаться при открытии приложения","Начинает вход в VPN сразу после запуска Forti Split.",
   "Включите, чтобы не нажимать «Подключить» при каждом запуске. Запрос доступа Windows и подтверждение 2FA при необходимости всё равно появятся.\r\n\r\nОставьте выключенным, если подключаетесь только по кнопке."),
  ["login"]=new("Рабочий логин","Имя вашей учётной записи для входа в корпоративный VPN.",
   "Введите тот же логин, который используете в FortiClient. Сохраните формат, выданный ИТ: короткое имя, DOMAIN\\имя или адрес почты. Пароль вводится отдельно в окне входа.\r\n\r\nЕсли оставить поле пустым, логин можно указать в окне входа.","demo.operator"),
  ["remember"]=new("Сохранять пароль","Сохраняет пароль VPN в защищённом хранилище Windows после успешного входа.",
   "Включите, если хотите подставлять пароль при следующем входе. Одноразовые коды 2FA не сохраняются.\r\n\r\nЕсли снять галочку и сохранить настройки, ранее сохранённый пароль для этой учётной записи будет удалён из хранилища. В JSON-профиль пароль не попадает."),
  ["rdp"]=new("Рабочий стол","Локальный файл .rdp с настройками вашего удалённого рабочего стола.",
   "Нажмите «Выбрать файл RDP…» и найдите .rdp-файл, который вы уже открываете для работы или получили от ИТ. Здесь нужен путь к файлу на компьютере.\r\n\r\nЕсли RDP не используете, оставьте поле пустым и выключите «Открывать RDP после подключения». Настройки компьютера и шлюза берутся из самого .rdp-файла.",@"C:\Demo\Work\sample.rdp"),
  ["vpn"]=new("Сервер VPN","HTTPS-адрес сервера входа в VPN, выданный вашим ИТ-отделом.",
   "Перенесите адрес и порт из настройки подключения FortiClient. Формат: https://имя-сервера:порт. Если порт стандартный 443, его можно не писать.\r\n\r\nАдрес рабочего сайта сюда не добавляется: для сайтов есть отдельное поле ниже. Если VPN уже подключается, сохраняйте существующее значение.","https://vpn.demo.example.org:8443"),
  ["tc-program"]=new("Программа TrueConf","Путь к установленной программе TrueConf.exe на этом компьютере.",
   "Нажмите «Выбрать TrueConf…» и выберите исполняемый файл установленного клиента. Здесь нужен путь к программе, а не адрес сервера.\r\n\r\nЕсли TrueConf не используете, выключите его автозапуск и оставьте поле пустым.",@"C:\Demo\Apps\TrueConf\TrueConf.exe"),
  ["tc-server"]=new("Сервер TrueConf","Имя или IPv4 рабочего сервера TrueConf, доступ к которому нужен через VPN.",
   "Укажите сервер, используемый вашим клиентом TrueConf. Узнать его можно в настройках TrueConf или у ИТ. Вводите только имя либо IPv4: без https://, порта и пути.\r\n\r\nForti Split добавляет сетевой маршрут к этому серверу. Само подключение и учётная запись в TrueConf настраиваются в TrueConf отдельно. Если программа не используется, поле можно оставить пустым.","video.demo.example.org"),
  ["tc-port"]=new("Порт TrueConf","Номер порта сервиса TrueConf; изменяйте его только по данным ИТ.",
   "Введите целое число от 1 до 65535. Текущее стандартное значение в приложении — 4307. Если ИТ не выдавал другой порт, оставьте его.\r\n\r\nСейчас это значение сохраняется в профиле. Forti Split не меняет настройки порта в самом TrueConf и не ограничивает VPN-маршрут этим портом.","4500"),
  ["sites"]=new("Рабочие сайты / имена / IPv4","Рабочие ресурсы, доступ к которым нужно направлять через VPN.",
   "Можно вводить полную ссылку, имя сервера или IPv4. Разделяйте записи запятыми либо новой строкой.\r\n\r\nНапример, из https://portal.demo.example.org:9443/start приложение возьмёт только portal.demo.example.org. В браузере продолжайте использовать полную ссылку с портом и путём.\r\n\r\nДля имён IP определяется через DNS VPN при подключении и по кнопке «Применить рабочие адреса». Временный сбой DNS вызывает повторные попытки.\r\n\r\nЧтобы отказаться от фиксированного IP, замените именно его известным именем соответствующего сайта. Остальные рабочие адреса сохраните. Поле можно оставить пустым, если дополнительные сайты не нужны.","https://portal.demo.example.org:9443/start\r\nfiles.demo.example.org\r\n192.0.2.47"),
  ["domains"]=new("Рабочие DNS-домены","Окончания внутренних имён, которые должен разрешать корпоративный DNS VPN.",
   "Введите домены, выданные ИТ, через запятую. Например, для сервера files.demo.example.org домен может быть demo.example.org.\r\n\r\nЗдесь не нужны https://, порт, путь, IP, знак * или точка в начале. Используйте домены своей организации.\r\n\r\nПоле необязательное: для каждого имени, явно указанного в «Рабочие сайты / имена / IPv4», приложение создаёт отдельное DNS-правило. Существующие рабочие домены лучше сохранить.","demo.example.org, branch.example.org"),
  ["advanced"]=new("Дополнительные настройки","Открывает параметры сервера VPN, TrueConf и доступа к рабочим сайтам.",
   "Нажмите, чтобы развернуть или свернуть поля. Сворачивание ничего не удаляет.\r\n\r\nВо время работы VPN можно изменить рабочие сайты и DNS-домены и применить их отдельной кнопкой. Для изменения остальных параметров сначала отключите VPN."),
  ["apply-sites"]=new("Применить рабочие адреса","Сохраняет список сайтов и DNS-доменов и обновляет доступ к ним.",
   "1. Добавьте сайты по именам или ссылкам и при необходимости DNS-домены.\r\n2. Нажмите эту кнопку.\r\n3. Дождитесь окончания обновления; результат появится на вкладке «Работа».\r\n\r\nПри активном VPN переподключение и новый код 2FA не нужны. Приложение узнает актуальные IP и обновит свои маршруты. Без VPN настройки сохранятся для следующего подключения. Если рабочие адреса уже применены, отдельно нажимать «Сохранить» не нужно."),
  ["save"]=new("Сохранить","Сохраняет заполненные поля и выбранные опции для следующих подключений.",
   "Заполните обязательный сервер VPN, проверьте выбранные файлы и нажмите «Сохранить». Пароль вводится отдельно при входе.\r\n\r\nВо время активного VPN эта кнопка недоступна. Для рабочих сайтов и DNS-доменов используйте «Применить рабочие адреса». Для остальных настроек сначала отключите VPN."),
  ["import"]=new("Импорт профиля","Заполняет настройки из приватного JSON-профиля вашей организации.",
   "Выберите файл .json, полученный от ИТ или экспортированный ранее из Forti Split для Windows. После импорта проверьте логин и локальные пути к файлам, затем нажмите «Сохранить».\r\n\r\nИмпорт не подключает VPN. Пароли и коды 2FA в профиль не входят."),
  ["export"]=new("Экспорт профиля","Сохраняет текущие настройки в файл для резервной копии или переноса.",
   "Выберите место для файла .local.json. Он содержит серверы, рабочие адреса, логин, пути к программам и выбранные опции. Пароля и кодов 2FA в нём нет.\r\n\r\nНа другом компьютере локальные пути могут потребовать изменения. Передавайте профиль только через разрешённый внутренний канал: корпоративные адреса и логин являются приватными данными.")
 };
 internal static SettingsHelpTopic Get(string key)=>Topics[key];
}

internal sealed class SettingsHelpDialog : Form
{
 internal SettingsHelpDialog(SettingsHelpTopic topic)
 {
  Text="Как заполнить: "+topic.Title;ClientSize=new Size(680,540);MinimumSize=new Size(560,420);StartPosition=FormStartPosition.CenterParent;
  Font=new Font("Segoe UI",11);BackColor=Color.White;MinimizeBox=false;MaximizeBox=false;
  var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),ColumnCount=1,RowCount=3};
  layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.AutoSize));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.AutoSize));Controls.Add(layout);
  layout.Controls.Add(new Label{Text=topic.Title,AutoSize=true,MaximumSize=new Size(620,0),Font=new Font("Segoe UI",18),Margin=new Padding(0,0,0,14)},0,0);
  layout.Controls.Add(new RichTextBox{Text=topic.Content(),ReadOnly=true,DetectUrls=false,BorderStyle=BorderStyle.None,BackColor=Color.White,ForeColor=Color.FromArgb(35,45,50),Font=Font,Dock=DockStyle.Fill,ScrollBars=RichTextBoxScrollBars.Vertical,Margin=new Padding(0,0,0,16),AccessibleName="Инструкция по заполнению"},0,1);
  var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoSize=true,FlowDirection=FlowDirection.RightToLeft,WrapContents=false,Margin=Padding.Empty};
  var close=new Button{Text="Понятно",DialogResult=DialogResult.OK,Width=130,Height=40,FlatStyle=FlatStyle.Flat,Margin=Padding.Empty};actions.Controls.Add(close);layout.Controls.Add(actions,0,2);AcceptButton=close;CancelButton=close;
 }
}
